class Solution {
    public int longestDecomposition(String text) {
        int n = text.length(), res = 0;
        int lo = 0, hi = n - 1;
        String left = "", right = "";
        while (lo < hi) {
            left += text.charAt(lo);
            right = text.charAt(hi) + right;
            if (left.equals(right)) {
                res += 2;
                left = "";
                right = "";
            }
            lo++;
            hi--;
        }
        if (lo == hi || !left.isEmpty()) res++;
        return res;
    }
}

class Solution {
    public int longestDecomposition(String text) {
        int n = text.length();
        int count = 0;
        long MOD = 1000000007L;
        long BASE = 31L;
        int lo = 0, hi = n - 1;
        long leftHash = 0, rightHash = 0;
        long power = 1;
        int len = 0;
        while (lo < hi) {
            leftHash = (leftHash * BASE + (text.charAt(lo) - 'a' + 1)) % MOD;
            rightHash = (rightHash + (text.charAt(hi) - 'a' + 1) * power) % MOD;
            power = power * BASE % MOD;
            len++;
            if (leftHash == rightHash) {
                boolean match = true;
                for (int k = 0; k < len; k++) {
                    if (text.charAt(lo - len + 1 + k) != text.charAt(hi + k)) {
                        match = false;
                        break;
                    }
                }
                if (match) {
                    count += 2;
                    leftHash = 0;
                    rightHash = 0;
                    power = 1;
                    len = 0;
                }
            }
            lo++;
            hi--;
        }
        if (lo == hi || len > 0) count++;
        return count;
    }
}
